<?php
require_once __DIR__ . '/../includes/functions.php'; require_role(['admin']); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');$id=(int)($_POST['id']??0);if($name==='')$error='Category name is required.';else{try{if($id){$s=$conn->prepare('UPDATE categories SET name=?,description=? WHERE id=?');$s->bind_param('ssi',$name,$desc,$id);}else{$s=$conn->prepare('INSERT INTO categories(name,description) VALUES(?,?)');$s->bind_param('ss',$name,$desc);}$s->execute();log_activity($conn,$id?'UPDATE':'CREATE','categories',$id?:$conn->insert_id,'Category saved');flash('success','Category saved.');redirect('admin/categories.php');}catch(Throwable $e){$error='Could not save category. Name may already exist.';}}}
$edit=null;if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$s=$conn->prepare('SELECT * FROM categories WHERE id=?');$s->bind_param('i',$id);$s->execute();$edit=$s->get_result()->fetch_assoc();}
layout_header('Categories');
?>
<?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><div class="grid two section-gap"><section class="card"><h2><?= $edit?'Edit':'Add' ?> category</h2><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>Category name<input name="name" required value="<?= e($edit['name']??'') ?>"></label><label>Description<textarea name="description"><?= e($edit['description']??'') ?></textarea></label><button class="btn">Save category</button></form></section><section class="card"><h2>Categories</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Description</th><th></th></tr></thead><tbody><?php $q=$conn->query('SELECT * FROM categories ORDER BY name');while($c=$q->fetch_assoc()): ?><tr><td><?= e($c['name']) ?></td><td><?= e($c['description']) ?></td><td><a class="btn btn-small btn-action btn-edit" href="?edit=<?= $c['id'] ?>">Edit</a></td></tr><?php endwhile; ?></tbody></table></div></section></div>
<?php layout_footer(); ?>
